            <div className="flex-1 overflow-y-auto p-4 bg-gray-50 pb-32">
               <div className="grid grid-cols-3 gap-3 max-w-md mx-auto relative">
                 {locations.map(loc => (
                    <SortableItem key={loc} loc={loc} active={loc === activeLocation} draggingLoc={draggingLoc} onDragStart={setDraggingLoc} onDragEnd={() => setDraggingLoc(null)} onDragTrigger={handleDrag} />
