      {showTeamModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60" onClick={() => setShowTeamModal(false)}>
          <div className="bg-white rounded-3xl w-full max-w-sm p-8 shadow-2xl relative" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold mb-2 text-gray-900">팀원과 데이터 공유</h3>
            <p className="text-gray-500 text-sm mb-6">
              작성한 점검 데이터를 파일로 만들어 공유하거나,<br/>
