            </p>
            {!preparedFile ? (
              <div className="space-y-4">
                <button onClick={handlePrepareData} disabled={isProcessing} className="w-full py-4 bg-brand-600 text-white font-bold rounded-xl shadow-md">내 데이터 파일 생성</button>
                <input type="file" ref={fileInputRef} onChange={handleMergeFileChange} accept=".json" className="hidden" />
                <button onClick={() => fileInputRef.current?.click()} disabled={isProcessing} className="w-full py-4 bg-yellow-400 text-yellow-950 font-bold rounded-xl shadow-md">팀원 파일 합치기</button>
              </div>
            ) : (
              <div className="space-y-4 text-center">
                <p className="text-green-600 font-bold mb-4">데이터 파일이 준비되었습니다.</p>
                <button onClick={executeDownload} className="w-full py-4 bg-brand-600 text-white font-bold rounded-xl shadow-md">파일 내보내기</button>
                <button onClick={() => setPreparedFile(null)} className="w-full py-2 text-gray-400">뒤로 가기</button>
              </div>
            )}
            {isProcessing && (
              <div className="absolute inset-0 bg-white/95 rounded-3xl flex flex-col items-center justify-center z-20">
                <RefreshCw className="animate-spin text-brand-600 mb-4" size={40} />
                <p className="text-brand-800 font-bold">{processingMsg}</p>
              </div>
            )}
            {!isProcessing && !preparedFile && (
              <button onClick={() => setShowTeamModal(false)} className="w-full mt-4 py-2 text-gray-400">닫기</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

